style.css:
@-moz-document url-prefix("https://www.roblox.com/my/avatar") {
/* Fondo oscuro con efecto dorado */
    body {
        background: linear-gradient(to bottom, #111, #222);
        color: #FFD700;
    }
    
    /* Estilizar la sección del avatar */
    .avatar-container {
        background: #1A1A1A;
        border: 2px solid #FFD700;
        border-radius: 10px;
        box-shadow: 0 0 15px rgba(255, 215, 0, 0.5);
        padding: 20px;
    }
    
    /* Personalización de los botones de avatar */
    .avatar-button,
    .btn-primary {
        background: #FFD700;
        color: black;
        border-radius: 5px;
        font-weight: bold;
    }
    .avatar-button:hover,
    .btn-primary:hover {
        background: #E6C200;
    }
    
    /* Texto dorado con sombras elegantes */
    h1, h2, h3, h4, h5, h6 {
        color: #FFD700;
        text-shadow: 2px 2px 5px rgba(255, 215, 0, 0.5);
    }
    
    /* Modificación de los enlaces */
    a {
        color: #FFD700;
        text-decoration: none;
    }
    a:hover {
        color: #E6C200;
        text-decoration: underline;
    }
}
